import { Box, Paper, Typography, useMediaQuery, useTheme } from '@mui/material'
import { useCallback, useEffect, useMemo, useRef } from 'react'
import type { UseGithubAuthResult } from '../auth/use_github_auth'
import {
    DEFAULT_CARD_TYPES,
    DEFAULT_ACTIONS_FOLDER,
    DEFAULT_ARCHIVED_FOLDER,
    DEFAULT_PROJECT_FOLDER,
    DEFAULT_RELEASES_FOLDER,
    DEFAULT_STATES,
    defaultColumnAccent,
} from '../data/data_types'
import { dataService } from '../services/data/data_service'
import { dialogService } from '../services/dialog_service'
import { getElectronLifecycleBridge, type ElectronLifecycleBridge } from '../services/electron_lifecycle_bridge'
import { openFilesService } from '../services/open_files_service'
import type { OpenDocument } from '../services/open_files_service'
import { telemetryService } from '../services/telemetry/telemetry_service'
import { workspaceViewService } from '../services/project/workspace_view_service'
import { workspaceNavigationService, type WorkspaceOpenRequest } from '../services/project/workspace_navigation_service'
import { projectPersistenceService } from '../services/project/project_persistence_service'
import { CardView } from './card_view/card_view'
import { MobileCardViewMenu } from './card_view/mobile_card_view_menu'
import { MobileCardView } from './card_view/mobile_card_view'
import { CardActionPopupHost } from './actions/run/popup/card_action_popup_host'
import { flushMarkdownEditors } from './editor/markdown_editor_flush'
import { useProjectReference } from './hooks/use_project_reference'
import { TextView } from './text_view/text_view'
import { FileTreeView } from './text_view/file_tree_view'
import { useProjectConfig } from './hooks/use_project_config'
import { useWorkingFolder } from './hooks/use_working_folder'
import { ProjectWorkspaceAvailability } from './project_workspace_availability'
import { MobileLayout } from './shell/mobile_layout'
import { MobileMainWindow } from './shell/mobile_main_window'
import { SplitLayout } from './shell/split_layout'

const WORKSPACE_PANEL_PADDING = 3

function openDocumentPath(document: OpenDocument) {
    return document.kind === 'card' ? document.getObject().path : document.getObject().sourcePath
}

function flushPendingCommits() {
    flushMarkdownEditors()
    void projectPersistenceService.flushPendingChanges().catch((error: unknown) => {
        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved' })
    })
}

async function flushAndConfirmPendingCommits(lifecycleBridge: ElectronLifecycleBridge, requestId: string) {
    try {
        flushMarkdownEditors()
        await projectPersistenceService.flushPendingChanges()
        lifecycleBridge.confirmFlush(requestId)
    } catch (error) {
        dialogService.error(error, { fallbackMessage: 'Pending changes could not be saved before closing' })
    }
}

function runWorkspaceEdit(action: () => void, fallbackMessage: string) {
    try {
        action()
    } catch (error) {
        dialogService.error(error, { fallbackMessage })
    }
}

interface ProjectWorkspaceProps {
    auth: UseGithubAuthResult
    isMenuOpen: boolean
    onLeftPanelInteraction: () => void
}

export function ProjectWorkspace(props: ProjectWorkspaceProps) {
    const { auth, isMenuOpen, onLeftPanelInteraction } = props
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const project = useProjectReference()
    const projectConfig = useProjectConfig()
    const workingFolder = useWorkingFolder()
    const cardTypes = projectConfig?.cardTypes ?? DEFAULT_CARD_TYPES
    const states = projectConfig?.states ?? DEFAULT_STATES
    const projectFolder = projectConfig?.projectFolder ?? DEFAULT_PROJECT_FOLDER
    const actionsFolder = projectConfig?.actionsFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ACTIONS_FOLDER}`
    const archivedFolder = projectConfig?.archivedFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_ARCHIVED_FOLDER}`
    const releasesFolder = projectConfig?.releasesFolder ?? `${DEFAULT_PROJECT_FOLDER}/${DEFAULT_RELEASES_FOLDER}`
    const mobileScrollContainerRef = useRef<HTMLDivElement>(null)
    const onLeftPanelInteractionRef = useRef(onLeftPanelInteraction)
    const statusColors = useMemo(() => new Map(
        states.map(({ color, state }, index) => [state, color ?? defaultColumnAccent(index)]),
    ), [states])

    useEffect(() => {
        onLeftPanelInteractionRef.current = onLeftPanelInteraction
    })

    const handleCreateFolder = useCallback(async (parentDirectory: string, name: string) => {
        await dataService.cards.createFolder(parentDirectory, name)
    }, [])

    const handleCreateMarkdownFile = useCallback(async (parentDirectory: string, name: string) => {
        await dataService.cards.createMarkdownFile(parentDirectory, name)
    }, [])

    const handleDeleteFile = useCallback(async (path: string) => {
        try {
            await dataService.cards.deleteFile(path)
            const document = openFilesService.getSnapshot().documents.find((candidate) => openDocumentPath(candidate) === path)
            if (document) openFilesService.closeDocument(document)
            workspaceViewService.clearSelectedPath(path)
            onLeftPanelInteractionRef.current()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `File delete failed: ${path}` })
            throw error
        }
    }, [])

    const handleDeleteFolder = useCallback(async (path: string) => {
        try {
            await dataService.cards.deleteFolder(path)
            const folderPrefix = `${path.replace(/\/+$/u, '')}/`
            const documents = openFilesService.getSnapshot().documents
            for (const document of documents) {
                const openPath = openDocumentPath(document)
                if (openPath?.startsWith(folderPrefix)) openFilesService.closeDocument(document)
            }
            const selectedPath = workspaceViewService.getSnapshot().selectedPath
            if (selectedPath?.startsWith(folderPrefix)) workspaceViewService.clearSelectedPath(selectedPath)
            onLeftPanelInteractionRef.current()
        } catch (error) {
            dialogService.error(error, { fallbackMessage: `Folder deletion failed: ${path}` })
            throw error
        }
    }, [])

    useEffect(() => {
        const handleBeforeUnload = (event: BeforeUnloadEvent) => {
            flushMarkdownEditors()
            const { hasPendingPush, hasPendingSave } = projectPersistenceService.getSnapshot()
            // In Electron, vetoing beforeunload silently cancels the window close (no confirm
            // dialog), leaving the app unclosable. The main process flushes pending commits on
            // quit instead, so only prompt in a plain browser build.
            if ((hasPendingPush || hasPendingSave) && !getElectronLifecycleBridge()) {
                event.preventDefault()
                event.returnValue = ''
            }

            flushPendingCommits()
        }

        const handleVisibilityChange = () => {
            if (document.visibilityState === 'hidden') flushPendingCommits()
        }

        const handleBlur = () => {
            flushMarkdownEditors()
            if (projectPersistenceService.getSnapshot().hasPendingSave) flushPendingCommits()
        }

        document.addEventListener('visibilitychange', handleVisibilityChange)
        window.addEventListener('beforeunload', handleBeforeUnload)
        window.addEventListener('blur', handleBlur)

        return () => {
            document.removeEventListener('visibilitychange', handleVisibilityChange)
            window.removeEventListener('beforeunload', handleBeforeUnload)
            window.removeEventListener('blur', handleBlur)
        }
    }, [])

    useEffect(() => {
        const lifecycleBridge = getElectronLifecycleBridge()
        if (!lifecycleBridge) return undefined

        return lifecycleBridge.onFlushRequested((requestId) => {
            void flushAndConfirmPendingCommits(lifecycleBridge, requestId)
        })
    }, [])

    useEffect(() => {
        const handleNavigationOpen = (event: Event) => {
            const { path } = (event as CustomEvent<WorkspaceOpenRequest>).detail
            // Reveal the card/file without changing the current view mode: highlight it in card view
            // and open it in the service-owned text-view tabs.
            workspaceViewService.selectPath(path)
            runWorkspaceEdit(() => openFilesService.openPath(path), `File open failed: ${path}`)
            telemetryService.trackEvent('navigation')
        }

        workspaceNavigationService.addEventListener('open', handleNavigationOpen)

        return () => workspaceNavigationService.removeEventListener('open', handleNavigationOpen)
    }, [])

    const fileTree = (
        <Box
            aria-label="File tree"
            sx={{ bgcolor: 'action.hover', display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0 }}
        >
            <FileTreeView
                actionsFolder={actionsFolder}
                archivedFolder={archivedFolder}
                cardTypes={cardTypes}
                onCreateFolder={handleCreateFolder}
                onCreateMarkdownFile={handleCreateMarkdownFile}
                onDeleteFile={handleDeleteFile}
                onDeleteFolder={handleDeleteFolder}
                onLeftPanelInteraction={onLeftPanelInteraction}
                projectFolder={projectFolder}
                releasesFolder={releasesFolder}
                statusColors={statusColors}
                workingFolder={workingFolder}
            />
        </Box>
    )
    const textView = (
        <Paper
            elevation={0}
            sx={{
                border: 1,
                borderColor: 'divider',
                borderRadius: 2,
                boxSizing: 'border-box',
                display: 'flex',
                height: '100%',
                minHeight: 0,
                overflow: 'hidden',
                p: WORKSPACE_PANEL_PADDING,
            }}
        >
            <TextView
                actionsFolder={actionsFolder}
                archivedFolder={archivedFolder}
                cardTypes={cardTypes}
                projectFolder={projectFolder}
                releasesFolder={releasesFolder}
                states={states}
            />
        </Paper>
    )

    const workspace = (
        <ProjectWorkspaceAvailability>
            {isMobile ? <MobileLayout content={textView} /> : <SplitLayout left={fileTree} right={textView} />}
            {isMobile ? (
                <MobileCardView cardTypes={cardTypes} states={states} statusColors={statusColors} />
            ) : (
                <CardView cardTypes={cardTypes} states={states} statusColors={statusColors} />
            )}
            <CardActionPopupHost />
        </ProjectWorkspaceAvailability>
    )
    const navigation = project ? fileTree : (
        <Box sx={{ p: 2 }}>
            <Typography color="text.secondary" variant="body2">
                No project navigation available.
            </Typography>
        </Box>
    )

    return (
        <Box
            aria-label="Project workspace"
            component="section"
            sx={{ display: 'flex', flex: 1, minHeight: 0, overflow: isMobile ? 'unset' : 'hidden' }}
        >
            {isMobile ? (
                <MobileMainWindow
                    auth={auth}
                    cardNavigation={project ? <MobileCardViewMenu onSelected={onLeftPanelInteraction} states={states} /> : null}
                    isMenuOpen={isMenuOpen}
                    leftPanel={navigation}
                    onCloseMenu={onLeftPanelInteraction}
                    rightPanel={workspace}
                    rightPanelContainerRef={mobileScrollContainerRef}
                    showNavigationInCards={!project}
                />
            ) : workspace}
        </Box>
    )
}

import type { ActionService } from '../actions/action_service'
import { ACTION_PERSISTENCE_CHANGED_EVENT } from '../actions/action_service_events'
import type { DataService } from '../data/data_service'
import { register } from '../service_injector'
import type { OpenFilesService } from '../open_files_service'

export type LocalSaveState = 'dirty' | 'saved' | 'saving'

export interface ProjectPersistenceSnapshot {
    hasPendingPush: boolean
    hasPendingSave: boolean
    localSaveState: LocalSaveState
}

export interface ProjectPersistenceServiceDependencies {
    actionService: ActionService
    dataService: DataService
    openFilesService: OpenFilesService
}

const INITIAL_SNAPSHOT: ProjectPersistenceSnapshot = {
    hasPendingPush: false,
    hasPendingSave: false,
    localSaveState: 'saved',
}

export class ProjectPersistenceService extends EventTarget {
    private dependencies: ProjectPersistenceServiceDependencies | null = null
    private snapshot = INITIAL_SNAPSHOT

    constructor() {
        super()
        register('projectPersistenceService', this)
    }

    init(dependencies: ProjectPersistenceServiceDependencies) {
        if (
            this.dependencies?.actionService === dependencies.actionService
            && this.dependencies.dataService === dependencies.dataService
            && this.dependencies.openFilesService === dependencies.openFilesService
        ) return

        this.removeDependencyListeners()
        this.dependencies = dependencies
        dependencies.actionService.addEventListener(ACTION_PERSISTENCE_CHANGED_EVENT, this.handleDependencyChanged)
        dependencies.dataService.addEventListener('persistenceChanged', this.handleDependencyChanged)
        dependencies.openFilesService.addEventListener('documentChanged', this.handleDependencyChanged)
        dependencies.openFilesService.addEventListener('removed', this.handleDependencyChanged)
        this.reconcileSnapshot()
    }

    getSnapshot(): ProjectPersistenceSnapshot {
        return this.snapshot
    }

    async flushPendingChanges() {
        const { actionService, dataService, openFilesService } = this.requireDependencies()
        if (actionService.draftStore.hasPendingDrafts()) await actionService.draftStore.flushDrafts()
        for (const document of openFilesService.getRegisteredDocuments()) {
            if (document.kind === 'card' && document.dirty) {
                dataService.cards.updateCardBody(document.path, document.getDraft().content, document.createSaveReference())
            }
        }
        if (dataService.getPersistenceSnapshot().hasPendingFileCommit) await dataService.cards.flushPendingCommits()
    }

    private readonly handleDependencyChanged = () => {
        this.reconcileSnapshot()
    }

    private reconcileSnapshot() {
        const { actionService, dataService, openFilesService } = this.requireDependencies()
        const { hasPendingFileCommit, hasPendingPush, isSaving } = dataService.getPersistenceSnapshot()
        const hasDirtyDocument = openFilesService.getRegisteredDocuments().some(({ dirty }) => dirty)
        const hasPendingSave = isSaving || hasPendingFileCommit || hasDirtyDocument || actionService.draftStore.hasPendingDrafts()
        const nextSnapshot: ProjectPersistenceSnapshot = {
            hasPendingPush,
            hasPendingSave,
            localSaveState: isSaving ? 'saving' : hasPendingSave ? 'dirty' : 'saved',
        }
        if (ProjectPersistenceService.isSameSnapshot(this.snapshot, nextSnapshot)) return

        this.snapshot = nextSnapshot
        this.dispatchEvent(new CustomEvent<ProjectPersistenceSnapshot>('changed', { detail: nextSnapshot }))
    }

    private removeDependencyListeners() {
        if (!this.dependencies) return

        this.dependencies.actionService.removeEventListener(ACTION_PERSISTENCE_CHANGED_EVENT, this.handleDependencyChanged)
        this.dependencies.dataService.removeEventListener('persistenceChanged', this.handleDependencyChanged)
        this.dependencies.openFilesService.removeEventListener('documentChanged', this.handleDependencyChanged)
        this.dependencies.openFilesService.removeEventListener('removed', this.handleDependencyChanged)
    }

    private requireDependencies() {
        if (!this.dependencies) throw new Error('Project persistence service is not initialized')

        return this.dependencies
    }

    private static isSameSnapshot(first: ProjectPersistenceSnapshot, second: ProjectPersistenceSnapshot) {
        return first.hasPendingPush === second.hasPendingPush
            && first.hasPendingSave === second.hasPendingSave
            && first.localSaveState === second.localSaveState
    }
}

export const projectPersistenceService = new ProjectPersistenceService()

/**
 * Registry of mounted markdown editors with unflushed edits. Editors register a
 * flush callback while mounted; app-level lifecycle hooks (window blur, hide,
 * close, Electron quit) call `flushMarkdownEditors` so pending editor content
 * reaches `DataService` before commits are flushed.
 */

const flushCallbacks = new Set<() => void>()

export function registerMarkdownEditorFlush(flush: () => void) {
    flushCallbacks.add(flush)

    return () => {
        flushCallbacks.delete(flush)
    }
}

export function flushMarkdownEditors() {
    for (const flush of [...flushCallbacks]) flush()
}

const CONFIG_GET_DESKTOP_CHANNEL = 'md2-config:get-desktop';
const CONFIG_SET_DESKTOP_CHANNEL = 'md2-config:set-desktop';
const LIFECYCLE_FLUSH_DONE_CHANNEL = 'md2-lifecycle:flush-pending-commits-done';
const LIFECYCLE_FLUSH_REQUEST_CHANNEL = 'md2-lifecycle:flush-pending-commits';
const LOCAL_BRIDGE_EVENT_CHANNEL = 'md2-local-bridge:event';
const LOCAL_BRIDGE_INVOKE_CHANNEL = 'md2-local-bridge:invoke';
const LOCAL_BRIDGE_SUBSCRIBE_CHANNEL = 'md2-local-bridge:subscribe';
const LOCAL_BRIDGE_UNSUBSCRIBE_CHANNEL = 'md2-local-bridge:unsubscribe';
const REMARKABLE_IMPORT_FILES_CHANNEL = 'md2-remarkable:import-files';
const REMARKABLE_LIST_IMAGE_FILES_CHANNEL = 'md2-remarkable:list-image-files';
const REMARKABLE_TEST_CONNECTION_CHANNEL = 'md2-remarkable:test-connection';
const REMOTE_CONTROL_GET_STATUS_CHANNEL = 'md2-remote-control:get-status';
const REMOTE_CONTROL_START_CHANNEL = 'md2-remote-control:start';
const REMOTE_CONTROL_STATUS_CHANNEL = 'md2-remote-control:status';
const REMOTE_CONTROL_STOP_CHANNEL = 'md2-remote-control:stop';
const THEME_SET_MODE_CHANNEL = 'md2-theme:set-mode';
const UPDATE_AVAILABLE_CHANNEL = 'md2-update:available';
